#!/usr/bin/env node
// Generates src/generated/bodies.ts from the committed OpenAPI spec: for every
// operation with a JSON request body, one line naming its top-level fields,
// their types and which are required. Write tools append it to their
// description, so the model sees NinjaOne's own field names without a lookup.
//
// Usage: node scripts/gen-bodies.mjs [--check]
//   --check exits 1 when the generated file is out of date (CI drift guard).

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse } from 'yaml';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SPEC = join(ROOT, 'spec/ninjaone-public-api-v2.yaml');
const OUT = join(ROOT, 'src/generated/bodies.ts');
const MAX_FIELDS = 24;
const MAX_CHARS = 1200;

const spec = parse(readFileSync(SPEC, 'utf8'), { maxAliasCount: -1 });
const schemas = spec.components?.schemas ?? {};

function deref(schema, seen = new Set()) {
  if (!schema || typeof schema !== 'object') return schema;
  if (schema.$ref) {
    const name = schema.$ref.split('/').pop();
    if (seen.has(name)) return {};
    seen.add(name);
    return deref(schemas[name], seen);
  }
  if (Array.isArray(schema.allOf)) {
    const merged = { type: 'object', properties: {}, required: [] };
    for (const part of schema.allOf.map((p) => deref(p, seen))) {
      Object.assign(merged.properties, part?.properties ?? {});
      merged.required.push(...(part?.required ?? []));
    }
    return merged;
  }
  return schema;
}

function typeName(schema) {
  const s = deref(schema);
  if (!s || typeof s !== 'object') return 'any';
  if (Array.isArray(s.enum)) return s.enum.slice(0, 6).map((v) => JSON.stringify(v)).join('|') + (s.enum.length > 6 ? '|...' : '');
  if (s.type === 'array') return `${typeName(s.items)}[]`;
  if (s.type === 'object' || s.properties) return 'object';
  if (s.format === 'date-time') return 'date-time';
  return s.type ?? 'any';
}

function describeBody(schema) {
  let s = deref(schema);
  let prefix = '';
  if (s?.type === 'array') {
    prefix = 'Each item: ';
    s = deref(s.items);
  }
  const props = s?.properties ?? {};
  const required = new Set(s?.required ?? []);
  const names = Object.keys(props);
  if (names.length === 0) return '';
  const ordered = [...names.filter((n) => required.has(n)), ...names.filter((n) => !required.has(n))];
  const parts = ordered.slice(0, MAX_FIELDS).map((n) => `${n} (${typeName(props[n])}${required.has(n) ? ', required' : ''})`);
  const more = names.length > MAX_FIELDS ? `, and ${names.length - MAX_FIELDS} more` : '';
  let text = `${prefix}Fields: ${parts.join(', ')}${more}.`;
  if (text.length > MAX_CHARS) text = text.slice(0, MAX_CHARS - 4) + '...';
  return text;
}

const docs = {};
for (const [, item] of Object.entries(spec.paths)) {
  for (const [method, op] of Object.entries(item)) {
    if (!['post', 'put', 'patch', 'delete'].includes(method) || !op?.operationId) continue;
    const content = op.requestBody?.content ?? {};
    const json = content['application/json'] ?? content['*/*'];
    if (!json?.schema) continue;
    const text = describeBody(json.schema);
    if (text) docs[op.operationId] = text;
  }
}

const sorted = Object.fromEntries(Object.entries(docs).sort(([a], [b]) => a.localeCompare(b)));
const body =
  '// Generated by scripts/gen-bodies.mjs from spec/ninjaone-public-api-v2.yaml. Do not edit.\n' +
  `// ${Object.keys(sorted).length} operations with a JSON request body.\n\n` +
  `export const BODY_DOCS: Readonly<Record<string, string>> = ${JSON.stringify(sorted, null, 2)};\n`;

if (process.argv.includes('--check')) {
  const current = existsSync(OUT) ? readFileSync(OUT, 'utf8') : '';
  if (current !== body) {
    console.error('src/generated/bodies.ts is out of date. Run npm run gen:bodies and commit the result.');
    process.exit(1);
  }
  console.log('src/generated/bodies.ts is current.');
} else {
  mkdirSync(dirname(OUT), { recursive: true });
  writeFileSync(OUT, body);
  console.log(`Wrote ${OUT}: ${Object.keys(sorted).length} request bodies.`);
}
